def type_of(expr):
    k = expr[0]
    if k == "num":
        return "Nat"
    if k == "bool":
        return "Bool"
    if k == "pair":
        a = type_of(expr[1])
        b = type_of(expr[2])
        if a == "error" or b == "error":
            return "error"
        return "(" + a + " x " + b + ")"
    if k == "add":
        if type_of(expr[1]) == "Nat" and type_of(expr[2]) == "Nat":
            return "Nat"
        return "error"
    if k == "if":
        c = type_of(expr[1])
        a = type_of(expr[2])
        b = type_of(expr[3])
        if c == "Bool" and a == b and a != "error":
            return a
        return "error"
    return "error"

