practice.solution:
def infer(term, ctx):
    k = term[0]
    if k == "var":
        if term[1] in ctx:
            return ctx[term[1]]
        return "error"
    if k == "lam":
        c = {}
        for key in ctx:
            c[key] = ctx[key]
        c[term[1]] = term[2]
        r = infer(term[3], c)
        if r == "error":
            return "error"
        return ["->", term[2], r]
    if k == "app":
        f = infer(term[1], ctx)
        a = infer(term[2], ctx)
        if f == "error" or a == "error":
            return "error"
        if isinstance(f, list) and f[0] == "->" and f[1] == a:
            return f[2]
        return "error"
    return "error"

