def reduce_word(w):
    out = []
    for ch in w:
        if len(out) > 0 and out[len(out) - 1] != ch and out[len(out) - 1].lower() == ch.lower():
            out.pop()
        else:
            out.append(ch)
    return "".join(out)

def word_inverse(w):
    r = []
    i = len(w) - 1
    while i >= 0:
        ch = w[i]
        if ch == ch.lower():
            r.append(ch.upper())
        else:
            r.append(ch.lower())
        i = i - 1
    return "".join(r)

