def components(n, edges):
    parent = []
    for i in range(n):
        parent.append(i)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    for e in edges:
        a = find(e[0])
        b = find(e[1])
        if a != b:
            parent[a] = b
    roots = {}
    for i in range(n):
        roots[find(i)] = 1
    return len(roots)

def is_equiv(f):
    n = len(f)
    seen = {}
    for x in f:
        if x < 0 or x >= n:
            return False
        if x in seen:
            return False
        seen[x] = 1
    return len(seen) == n

def quasi_inverse(f):
    g = []
    for i in range(len(f)):
        g.append(0)
    for i in range(len(f)):
        g[f[i]] = i
    return g

def count_equivs(n):
