def winding(w):
    n = 0
    for ch in w:
        if ch == "l":
            n = n + 1
        elif ch == "L":
            n = n - 1
    return n

def loop_power(n):
    if n >= 0:
        return "l" * n
    return "L" * (0 - n)

def encode(w):
    n = 0
    for ch in w:
        if ch == "l":
            n = n + 1
        elif ch == "L":
            n = n - 1
    if n >= 0:
        return [n, "l" * n]
    return [n, "L" * (0 - n)]

